require dirname(__DIR__).'/app/bootstrap.php';require_permission('ai.access');require dirname(__DIR__).'/app/layout.php';require dirname(__DIR__).'/app/ai.php';$error='';$userId=(int)current_user()['id'];$conversationId=(int)($_GET['conversation']??0);$conversation=$conversationId?one('SELECT * FROM ai_conversations WHERE id=? AND business_id=? AND user_id=?',[$conversationId,bid(),$userId]):null;if($conversationId&&!$conversation){http_response_code(404);exit('Conversation not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'chat';if($action==='clear'){if($conversation){transaction(function()use($conversationId,$userId){query('DELETE m FROM ai_messages m JOIN ai_conversations c ON c.id=m.conversation_id WHERE c.id=? AND c.business_id=? AND c.user_id=?',[$conversationId,bid(),$userId]);query('DELETE FROM ai_conversations WHERE id=? AND business_id=? AND user_id=?',[$conversationId,bid(),$userId]);});}flash('Conversation cleared.');redirect('ai-assistant.php');}if($action==='proposal'){$p=prepare_task_proposal(required_text('title',200),required_text('due_date'),(string)($_POST['description']??''));$_SESSION['approval_tokens'][$p['id']]=$p['token'];flash('Task proposal prepared. An Owner must explicitly approve it before a task is created.');redirect('ai-assistant.php');}if($action==='approve'||$action==='reject'){$id=(int)($_POST['proposal_id']??0);approve_task_proposal($id,(string)($_POST['token']??''),$action==='approve');unset($_SESSION['approval_tokens'][$id]);flash($action==='approve'?'Approved task created.':'Proposal rejected.');redirect('ai-assistant.php');}
$message=required_text('message',4000);$tool=required_text('tool',40);$context=ai_context($tool,(string)($_POST['search_term']??''));$provider=one('SELECT * FROM ai_provider_configs WHERE business_id=? AND active=1 ORDER BY id DESC LIMIT 1',[bid()]);if(!$provider)throw new DomainException('No active provider is configured. Open Settings → AI & Integrations to connect a provider.');$calls=(int)scalar("SELECT COUNT(*) FROM activity_logs WHERE business_id=? AND user_id=? AND action='ai.request' AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)",[bid(),$userId]);if($calls>=20)throw new DomainException('Hourly limit reached (20 requests). Please try again later.');audit('ai.request','ai',null,['provider_id'=>$provider['id'],'tool'=>$tool]);$answer=call_provider($provider,$message,$context);
if(setting('ai_history',true)){if(!$conversationId){query('INSERT INTO ai_conversations(business_id,user_id,title) VALUES(?,?,?)',[bid(),$userId,mb_substr($message,0,100)]);$conversationId=(int)db()->lastInsertId();}transaction(function()use($conversationId,$message,$answer){foreach(['user'=>$message,'assistant'=>$answer] as $role=>$content)query('INSERT INTO ai_messages(conversation_id,role,content) VALUES(?,?,?)',[$conversationId,$role,$content]);});redirect('ai-assistant.php?conversation='.$conversationId);}$_SESSION['ai_ephemeral_answer']=$answer;redirect('ai-assistant.php');
}catch(DomainException $ex){$error=$ex->getMessage();}}
page_start('AI Assistant','A thoughtful assistant for your business. You stay in control.','<a class="btn" href="ai-assistant.php">'.icon('plus').' New conversation</a>');error_notice($error);if(!setting('ai_enabled',false)): ?><div class="notice info"><?= icon('shield-check') ?><span>External AI is disabled. The Owner can configure a provider and enable access in <a href="settings.php?tab=ai"><strong>AI & Integrations</strong></a>. No business data is sent while disabled.</span></div><?php endif; ?>
<div class="chat-layout"><aside class="panel chat-history"><a class="btn" href="ai-assistant.php"><?= icon('plus') ?> New conversation</a><h3>Your conversations</h3><?php foreach(rows('SELECT id,title FROM ai_conversations WHERE business_id=? AND user_id=? ORDER BY id DESC LIMIT 30',[bid(),$userId]) as $c): ?><a href="?conversation=<?= $c['id'] ?>"><?= icon('file-description') ?> <?= e($c['title']) ?></a><?php endforeach; ?><h3>Private by design</h3><p class="muted">Only your authorized records are available. API keys never reach this browser. Business changes need Owner approval.</p></aside><section class="panel chat-main"><?php $messages=$conversationId?rows('SELECT role,content,created_at FROM ai_messages WHERE conversation_id=? ORDER BY id DESC LIMIT 50',[$conversationId]):[];if(!$messages&&!isset($_SESSION['ai_ephemeral_answer'])): ?><div class="chat-welcome"><?= icon('sparkles') ?><div class="eyebrow">YOUR DIGITAL BUSINESS MANAGER</div><h2>A little insight goes a long way.</h2><p>Ask a question, explore your numbers, or find your next step. Let’s make sense of your business together.</p><div class="chat-suggestions"><?php foreach(['How is my business doing this month?','Which invoices have outstanding balances?','What should I focus on today?','Summarize my business cash flow.'] as $suggestion): ?><button type="button" data-suggestion="<?= e($suggestion) ?>"><?= e($suggestion) ?> <?= icon('arrow-up-right') ?></button><?php endforeach; ?></div></div><?php else:foreach(array_reverse($messages) as $m): ?><article class="message <?= e($m['role']) ?>"><small><?= $m['role']==='user'?'You':'YBT Assistant' ?></small><?= e($m['content']) ?></article><?php endforeach;if(isset($_SESSION['ai_ephemeral_answer'])): ?><article class="message"><small>YBT Assistant · History disabled</small><?= e($_SESSION['ai_ephemeral_answer']) ?></article><?php unset($_SESSION['ai_ephemeral_answer']);endif;endif; ?><form method="post" class="chat-form"><?php csrf_field(); ?><input type="hidden" name="action" value="chat"><label class="sr-only" for="chat-message">Your message</label><input id="chat-message" name="message" placeholder="Ask something about your business..." maxlength="4000" required><button class="btn primary" aria-label="Send message"><?= icon('send') ?></button><div class="full chat-options"><label>Data tool <select name="tool"><option value="summary">Business summary</option><option value="outstanding">Outstanding invoices</option><option value="customers">Search customers</option><option value="tasks">Upcoming tasks</option></select></label><input name="search_term" placeholder="Customer search term (optional)" aria-label="Customer search term"></div></form><div class="chat-disclaimer">Selected authorized data and your message are sent to the configured external provider. Verify important decisions.</div><?php if($conversation): ?><form method="post" class="clear-chat" data-confirm="Delete this conversation permanently?"><?php csrf_field(); ?><input type="hidden" name="action" value="clear"><button class="btn link">Clear conversation</button></form><?php endif; ?></section></div>
<?php if(setting('ai_enabled',false)&&can('ai.propose')&&can('tasks.create')): ?><section class="panel form-panel"><h2>Prepare a task proposal</h2><p>Prepare a change for review. Nothing is created until the Owner approves the exact proposal.</p><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="proposal"><div class="form-grid"><?php field('title',['Task title','text',true]);field('due_date',['Due date','date',true],date('Y-m-d'));field('description',['Description','textarea']); ?></div><div class="form-actions"><button class="btn primary">Prepare proposal</button></div></form></section><?php endif; ?>
<?php if(current_user()['role']==='owner'): $proposals=rows("SELECT p.*,u.name requester FROM ai_action_proposals p JOIN users u ON u.id=p.user_id AND u.business_id=p.business_id WHERE p.business_id=? AND p.status='Pending' AND p.expires_at>NOW() ORDER BY p.id DESC LIMIT 20",[bid()]);foreach($proposals as $p):$token=$_SESSION['approval_tokens'][$p['id']]??null;if(!$token){$token=bin2hex(random_bytes(32));query('UPDATE ai_action_proposals SET token_hash=? WHERE id=? AND business_id=?',[hash('sha256',$token),$p['id'],bid()]);$_SESSION['approval_tokens'][$p['id']]=$token;} ?><section class="panel form-panel"><h2>Owner approval required · Create one task</h2><p>Requested by <?= e($p['requester']) ?> · Expires <?= e($p['expires_at']) ?> · Current value: no task exists. Approving creates the task below.</p><pre class="proposal-payload"><?= e(json_encode(json_decode($p['payload'],true),JSON_PRETTY_PRINT)) ?></pre><form method="post" data-confirm="Approve this exact proposal and create the task?"><?php csrf_field(); ?><input type="hidden" name="proposal_id" value="<?= $p['id'] ?>"><input type="hidden" name="token" value="<?= e($token) ?>"><div class="form-actions"><button class="btn danger" name="action" value="reject">Reject</button><button class="btn primary" name="action" value="approve">Approve & create task</button></div></form></section><?php endforeach;endif;page_end(); ?>
